#!/usr/bin/env bash
# Build every kernels/*.c (hand-written) and build/gen/*.c (generated by
# lib/kgen.aura, see scripts/gen_kernel.sh) into build/kernels/lib<name>.so.
#   CC      C compiler (default: cc)
#   CFLAGS  extra flags (default: -O2)
# Generated sources also get -fwrapv (int64 wraparound, never UB) and no
# unused-label / unused-variable errors (the generator emits uniform labels).
set -euo pipefail
here="$(cd "$(dirname "$0")" && pwd)"
root="$(cd "$here/.." && pwd)"
out="$root/build/kernels"
mkdir -p "$out"
CC="${CC:-cc}"
CFLAGS="${CFLAGS:--O2}"
shopt -s nullglob
build_one() {  # src extra-flags tag
  local src="$1" extra="$2" tag="$3" name so
  name="$(basename "$src" .c)"
  so="$out/lib$name.so"
  if [ ! -f "$so" ] || [ "$src" -nt "$so" ] || [ "$here/sink_abi.h" -nt "$so" ]; then
    # shellcheck disable=SC2086
    "$CC" $CFLAGS $extra -std=c11 -Wall -Wextra -Werror -shared -fPIC -fvisibility=hidden \
      -I"$here" -o "$so" "$src"
    echo "built build/kernels/lib$name.so$tag"
  fi
}
for src in "$here"/*.c; do build_one "$src" "" ""; done
for src in "$root"/build/gen/*.c; do
  build_one "$src" "-fwrapv -Wno-unused-label -Wno-unused-variable" " (generated)"
done
